CREATE   FUNCTION CDN.NumerDokumentuTRN (
@p_GidTyp    INT,
@p_SpiTyp    INT,
@p_TrnTyp    INT,
@p_Numer     INT,
@p_Rok       INT,
@p_Seria	 VARCHAR(6)
)
RETURNS VARCHAR(30) AS
BEGIN
return CDN.NumerDokumentu(@p_GidTyp,@p_SpiTyp,@p_TrnTyp,@p_Numer,@p_Rok,@p_Seria,0)

END
